package in.flatmate.chat.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.time.LocalDateTime;

public final class ChatDtos {

    private ChatDtos() {
    }

    /**
     * clientMsgId is generated by the browser before the request is sent, so a
     * retry after a timeout hits the unique key instead of creating a duplicate.
     */
    public record SendMessageRequest(
            @NotBlank
            @Pattern(
                    regexp = "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
                    message = "must be a UUID")
            String clientMsgId,

            @NotBlank
            @Size(max = 2000, message = "must be at most 2000 characters")
            String body
    ) {
    }

    public record MessageDto(
            Long id,
            String clientMsgId,
            String conversationId,
            Long senderId,
            String senderName,
            String body,
            LocalDateTime createdAt
    ) {
    }

    public record ConversationDto(
            String id,
            Long otherUserId,
            String otherName,
            String lastMessage,
            LocalDateTime lastMessageAt,
            long unread
    ) {
    }

    public record ReadRequest(@NotNull Long lastReadMessageId) {
    }

    public record TypingEvent(Long userId, boolean typing) {
    }
}
